const STR = { en, es, fr };
let lang = 'en';

export const getLang = () => lang;
export const locale = () => LOCALE[lang];
export function setLang(l) { lang = STR[l] ? l : 'en'; document.documentElement.lang = lang; }

/** Look up a string; {name} placeholders are filled from vars. */
export function t(key, vars) {
  let s = STR[lang][key] ?? en[key] ?? key;
  if (vars) for (const [k, v] of Object.entries(vars)) s = s.replaceAll(`{${k}}`, v);
  return s;
}

/** Fill every element marked data-i18n / data-i18n-html / data-i18n-attr="attr:key". */
export function applyStatic(root = document) {
  root.querySelectorAll('[data-i18n]').forEach((el) => { el.textContent = t(el.dataset.i18n); });
  root.querySelectorAll('[data-i18n-html]').forEach((el) => { el.innerHTML = t(el.dataset.i18nHtml); });
  root.querySelectorAll('[data-i18n-attr]').forEach((el) => {
    for (const pair of el.dataset.i18nAttr.split(';')) { const [attr, key] = pair.split(':'); el.setAttribute(attr, t(key)); }
  });
}

export const missingKeys = () => Object.fromEntries(['es', 'fr'].map((l) => [l, Object.keys(en).filter((k) => !(k in STR[l]))]));
